(2265757, 310037, 53571, '<td valign="top">Wow, thats amazing.</td>', 'Wow, thats amazing.', '2006-03-28 07:33:46.000000', NULL, 1),
(2265761, 311777, 53571, '<td valign="top">Beautiful shot. I wish that ship wasnt in the background. Did you use a fill flash with this? If not, the light is gorgeous.</td>', 'Beautiful shot. I wish that ship wasnt in the background. Did you use a fill flash with this? If not, the light is gorgeous.', '2006-03-28 07:34:32.000000', NULL, 1),
(2265762, 312145, 53571, '<td valign="top">Somewhat plain and slightly blurry in my opinion. I would have given it a higher mark if it was sharper.</td>', 'Somewhat plain and slightly blurry in my opinion. I would have given it a higher mark if it was sharper.', '2006-03-28 07:35:10.000000', NULL, 1),
(2265764, 312034, 53571, '<td valign="top">Beautiful contrasts... blue, green, white.</td>', 'Beautiful contrasts... blue, green, white.', '2006-03-28 07:35:31.000000', NULL, 1),
(2265766, 309669, 53571, '<td valign="top">Really a fantastic shot. I wonder what it would have looked like 1/1000 of a second earlier?</td>', 'Really a fantastic shot. I wonder what it would have looked like 1/1000 of a second earlier?', '2006-03-28 07:36:04.000000', NULL, 1),
(2265769, 312196, 53571, '<td valign="top">Great shot.</td>', 'Great shot.', '2006-03-28 07:36:41.000000', NULL, 1),
