(2265771, 311947, 53571, '<td valign="top">Great idea. I Would like to see it be a little sharper.</td>', 'Great idea. I Would like to see it be a little sharper.', '2006-03-28 07:37:42.000000', NULL, 1),
(2265772, 311798, 53571, '<td valign="top">Great textures. The hot spots are slightly distracting to me.</td>', 'Great textures. The hot spots are slightly distracting to me.', '2006-03-28 07:38:08.000000', NULL, 1),
(2265773, 311567, 53571, '<td valign="top">Great idea. I think you almost got it. The color seems a little overworked to me. The hot spots in the drops themselves are distracting. Great effort.</td>', 'Great idea. I think you almost got it. The color seems a little overworked to me. The hot spots in the drops themselves are distracting. Great effort.', '2006-03-28 07:38:52.000000', NULL, 1),
(2265774, 311572, 53571, '<td valign="top">Beautiful.</td>', 'Beautiful.', '2006-03-28 07:39:05.000000', NULL, 1),
(2265775, 311444, 53571, '<td valign="top">I almost think this is too dark around the bark but upon repeated viewings I like the tonality. Good job.</td>', 'I almost think this is too dark around the bark but upon repeated viewings I like the tonality. Good job.', '2006-03-28 07:39:41.000000', NULL, 1),
(2265779, 312152, 53571, '<td valign="top">Nice moment. I wish it was a little sharper on his face.</td>', 'Nice moment. I wish it was a little sharper on his face.', '2006-03-28 07:39:59.000000', NULL, 1),
(2265780, 312039, 53571, '<td valign="top">The most interesting part of this photograph for me is the wonderful texture of the water BEHIND the birds. That is what I really interested in seeing.</td>', 'The most interesting part of this photograph for me is the wonderful texture of the water BEHIND the birds. That is what I really interested in seeing.', '2006-03-28 07:40:54.000000', NULL, 1),
(2265784, 310985, 53571, '<td valign="top">Creepy, spooky, and wonderful. I love this shot. The middle of the photograph might be a little dark. Maybe half a stop more light?</td>', 'Creepy, spooky, and wonderful. I love this shot. The middle of the photograph might be a little dark. Maybe half a stop more light?', '2006-03-28 07:41:39.000000', NULL, 1),
(2265786, 311851, 53571, '<td valign="top">Good effort. Does it need to be black and white? If so, why?</td>', 'Good effort. Does it need to be black and white? If so, why?', '2006-03-28 07:42:02.000000', NULL, 1),
(2265788, 312258, 53571, '<td valign="top">Wonderful. Are you painting with light here? It might be a little hot near the bottom of the image.</td>', 'Wonderful. Are you painting with light here? It might be a little hot near the bottom of the image.', '2006-03-28 07:42:36.000000', NULL, 1),
(2265792, 310784, 53571, '<td valign="top">This is a keeper. Is the vignetteing from a portal or from post production?</td>', 'This is a keeper. Is the vignetteing from a portal or from post production?', '2006-03-28 07:43:28.000000', NULL, 1),
(2265794, 311530, 53571, '<td valign="top">You have captured a very nice moment with great textures and wonderful light.</td>', 'You have captured a very nice moment with great textures and wonderful light.', '2006-03-28 07:43:57.000000', NULL, 1),
(2265798, 311229, 53571, '<td valign="top">The colors are great in this shot. However, I want to actually see something. I feel that you need to get closer to something in this composition.</td>', 'The colors are great in this shot. However, I want to actually see something. I feel that you need to get closer to something in this composition.', '2006-03-28 07:44:48.000000', NULL, 1),
(2265799, 310833, 53571, '<td valign="top">I rated this picture below average because I don''t feel the light, composition or focus is particularly well thought out. I enjoy the interesting effect you have created within the glass however (the red).</td>', 'I rated this picture below average because I don''t feel the light, composition or focus is particularly well thought out. I enjoy the interesting effect you have created within the glass however (the red).', '2006-03-28 07:45:50.000000', NULL, 1),
