(2267067, 311544, 23251, '<td valign="top">Nice capture!</td>', 'Nice capture!', '2006-03-28 17:08:24.000000', NULL, 1),
(2267117, 310998, 48717, '<td valign="top">Nice composition, fun pic, but there is a severe color cast on it.  The skintone is not balanced.</td>', 'Nice composition, fun pic, but there is a severe color cast on it.  The skintone is not balanced.', '2006-03-28 17:39:11.000000', NULL, 1),
(2267129, 311803, 48717, '<td valign="top">Love the look of the botom half of the pic with the moss and rocks and mini waterfalls, lots of visual interest here, but there is not as much interest in the top half and the eye wonders a bit landing on what seems to be a pile of dirt.  A differerent crop could have helped this photo a lot.</td>', 'Love the look of the botom half of the pic with the moss and rocks and mini waterfalls, lots of visual interest here, but there is not as much interest in the top half and the eye wonders a bit landing on what seems to be a pile of dirt.  A differerent crop could have helped this photo a lot.', '2006-03-28 17:48:37.000000', NULL, 1),
(2267136, 311247, 48717, '<td valign="top">Great sky.  Wish the windmill were more in focus, seems the sharper focus is on the bridge.</td>', 'Great sky.  Wish the windmill were more in focus, seems the sharper focus is on the bridge.', '2006-03-28 17:51:48.000000', NULL, 1),
(2267153, 310477, 3102, '<td valign="top">An interesting scene, but a little overboard on the editing for my tastes.</td>', 'An interesting scene, but a little overboard on the editing for my tastes.', '2006-03-28 18:00:51.000000', NULL, 1),
(2267156, 309339, 3102, '<td valign="top">I love the shades of blue in this one.  Great contrast with the plantlife, too!</td>', 'I love the shades of blue in this one.  Great contrast with the plantlife, too!', '2006-03-28 18:01:15.000000', NULL, 1),
(2267160, 312007, 3102, '<td valign="top">The composition seems a little awkward to me on this one.  I think the rowers seem a bit too far down in the shot, leaving a bit of unneccessary stuff at the top.</td>', 'The composition seems a little awkward to me on this one.  I think the rowers seem a bit too far down in the shot, leaving a bit of unneccessary stuff at the top.', '2006-03-28 18:02:25.000000', NULL, 1),
(2267164, 310089, 3102, '<td valign="top">Wow -- very neat shot!  I like the dreaminess of it.</td>', 'Wow -- very neat shot!  I like the dreaminess of it.', '2006-03-28 18:03:34.000000', NULL, 1),
