INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2267239, 310975, 35994, '<td valign="top">Beautiful shot, the reflection from the water on the duck is great. Nice shot!</td>', 'Beautiful shot, the reflection from the water on the duck is great. Nice shot!', '2006-03-28 18:44:07.000000', NULL, 1),
(2267240, 311851, 22533, '<td valign="top">A great picture of such a simple object!</td>', 'A great picture of such a simple object!', '2006-03-28 18:44:14.000000', NULL, 1),
(2267255, 309388, 40819, '<td valign="top">Did you know the same guy who designed this bridge, built the George Washington Bridge? I have a few images shot from this same park in my portfolio. Guess you shot this early in the morning. You can see more on my PAD blog. See my profile. Let me know if you want to go shoot together sometime.<br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=285999" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/40819/thumb/285999.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/40819/thumb/285999.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/40819/thumb/285999.jpg"/></a> <br/> <br/>Very nice shot just need a litle color here, very sharp and crisp.</td>', 'Did you know the same guy who designed this bridge, built the George Washington Bridge? I have a few images shot from this same park in my portfolio. Guess you shot this early in the morning. You can see more on my PAD blog. See my profile. Let me know if you want to go shoot together sometime.  Very nice shot just need a litle color here, very sharp and crisp.', '2006-03-28 18:47:56.000000', NULL, 1),
(2267270, 312094, 3102, '<td valign="top">Whoa.  The effects here just aren''t flattering at all.</td>', 'Whoa.  The effects here just aren''t flattering at all.', '2006-03-28 18:54:03.000000', NULL, 1),
(2267272, 312212, 41802, '<td valign="top">What a contrast, this amazing.</td>', 'What a contrast, this amazing.', '2006-03-28 18:56:09.000000', NULL, 1),
(2267276, 310062, 40797, '<td valign="top">One of my favorites! This is wonderful! The color combinations in this image all work so well together played against that cool coper faustet and I absolutely love that sweet adorable face, his expression is pricless. What a great capture.</td>', 'One of my favorites! This is wonderful! The color combinations in this image all work so well together played against that cool coper faustet and I absolutely love that sweet adorable face, his expression is pricless. What a great capture.', '2006-03-28 18:57:50.000000', NULL, 1),
