(2267388, 310062, 37103, '<td valign="top">Great dynami shot.  I love the drops of water sparying off her face and running down the chin.  Beautiful colors.</td>', 'Great dynami shot.  I love the drops of water sparying off her face and running down the chin.  Beautiful colors.', '2006-03-28 19:44:21.000000', NULL, 1),
