(2271889, 312035, 48717, '<td valign="top">Nice colors captured.</td>', 'Nice colors captured.', '2006-03-29 23:24:24.000000', NULL, 1),
(2271890, 311822, 48717, '<td valign="top">I love em simple and colorful.  wish the bottle were straight though, i.e. no nutrition info or logo visible.</td>', 'I love em simple and colorful.  wish the bottle were straight though, i.e. no nutrition info or logo visible.', '2006-03-29 23:24:46.000000', NULL, 1),
