(2272930, 312089, 24715, '<td valign="top">Funny!</td>', 'Funny!', '2006-03-30 09:43:14.000000', NULL, 1),
(2272996, 311869, 42100, '<td valign="top">Awesome macro, even without the reflection.  Very nice!</td>', 'Awesome macro, even without the reflection.  Very nice!', '2006-03-30 10:09:43.000000', NULL, 1),
(2273001, 311740, 42100, '<td valign="top">Very nice detail in the ice and I like the silky water below, but seems a little flat compositionally.</td>', 'Very nice detail in the ice and I like the silky water below, but seems a little flat compositionally.', '2006-03-30 10:13:31.000000', NULL, 1),
(2273005, 311624, 42100, '<td valign="top">This looks like a one take only kind of photo.  Looks like you had fun doing this and it came out very well.</td>', 'This looks like a one take only kind of photo.  Looks like you had fun doing this and it came out very well.', '2006-03-30 10:15:51.000000', NULL, 1),
(2273008, 311169, 42100, '<td valign="top">Beautiful sky!  Great job of composing this.  The person on the wall balances it very nicely.</td>', 'Beautiful sky!  Great job of composing this.  The person on the wall balances it very nicely.', '2006-03-30 10:17:12.000000', NULL, 1),
(2273191, 311632, 6008, '<td valign="top">The composition is good but there is just something about the shot that is lacking. I''m not sure if it''s the off-white snow or the general dullness of the light/colors. It''s a good shot, just lacking impact or the ''wow'' factor.</td>', 'The composition is good but there is just something about the shot that is lacking. I''m not sure if it''s the off-white snow or the general dullness of the light/colors. It''s a good shot, just lacking impact or the ''wow'' factor.', '2006-03-30 12:02:59.000000', NULL, 1),
(2273195, 312193, 6008, '<td valign="top">The scene looks a little haphazard with no main focal point. There is the path of the brook but the water is almost featureless. The sticks and other debris makes the image look a little cluttered also. Finding another angle or perspective would likely help.</td>', 'The scene looks a little haphazard with no main focal point. There is the path of the brook but the water is almost featureless. The sticks and other debris makes the image look a little cluttered also. Finding another angle or perspective would likely help.', '2006-03-30 12:05:36.000000', NULL, 1),
(2273199, 312069, 6008, '<td valign="top">The composition is good - I like how the stream leads up to the bridge where all the action is happening. The color combination of the blue and the orange is great. You''ve captured the essense of a late sunday afternoon at the park well.</td>', 'The composition is good - I like how the stream leads up to the bridge where all the action is happening. The color combination of the blue and the orange is great. You''ve captured the essense of a late sunday afternoon at the park well.', '2006-03-30 12:07:10.000000', NULL, 1),
(2273205, 311656, 6008, '<td valign="top">Pretty location. I like the flow through the image and the position of the fluffy white cloud is great, especially with the reflection. The muted colors give it a subtle tranquility.</td>', 'Pretty location. I like the flow through the image and the position of the fluffy white cloud is great, especially with the reflection. The muted colors give it a subtle tranquility.', '2006-03-30 12:09:54.000000', NULL, 1),
(2273211, 312140, 6008, '<td valign="top">Great shot! Wonderful sense of fun in this image. The clarity and stop action is great. Each child portrays a different aspect and emotion that adds a nice depth to the image.</td>', 'Great shot! Wonderful sense of fun in this image. The clarity and stop action is great. Each child portrays a different aspect and emotion that adds a nice depth to the image.', '2006-03-30 12:14:19.000000', NULL, 1),
(2273218, 311525, 6008, '<td valign="top">First impression when I saw this was that the depth of field looked artificial. After looking at it for a while it does work and has an almost 3d quality to it. The thickness of the light reflection on the far right steals a lot of the eyes'' attention, though. Reducing the size of the light beam may help some.</td>', 'First impression when I saw this was that the depth of field looked artificial. After looking at it for a while it does work and has an almost 3d quality to it. The thickness of the light reflection on the far right steals a lot of the eyes'' attention, though. Reducing the size of the light beam may help some.', '2006-03-30 12:18:24.000000', NULL, 1),
(2273221, 311940, 6008, '<td valign="top">Wonderful light, color, and clarity. Very beautiful.</td>', 'Wonderful light, color, and clarity. Very beautiful.', '2006-03-30 12:19:23.000000', NULL, 1),
(2273268, 309123, 45790, '<td valign="top">Somewhat interesting abstraction, it takes time to grow on me. Like the centered swirl.</td>', 'Somewhat interesting abstraction, it takes time to grow on me. Like the centered swirl.', '2006-03-30 12:43:15.000000', NULL, 1),
(2273271, 311798, 45790, '<td valign="top">Nice macro. Sharp and takes advantage of magnification by droplet.</td>', 'Nice macro. Sharp and takes advantage of magnification by droplet.', '2006-03-30 12:44:00.000000', NULL, 1),
(2273273, 311756, 45790, '<td valign="top">This is the sort of shot that needs to be viewed as a large print. The 640 pixel limit doesn''t do it justice.</td>', 'This is the sort of shot that needs to be viewed as a large print. The 640 pixel limit doesn''t do it justice.', '2006-03-30 12:44:54.000000', NULL, 1),
(2273275, 310691, 45790, '<td valign="top">Better if you cleaned the window first.</td>', 'Better if you cleaned the window first.', '2006-03-30 12:45:22.000000', NULL, 1),
