(2275906, 312218, 53571, '<td valign="top">The bottom 1/3 of the photograph is so out of focus it is distracting to me. Subract that and I love the textures, tones, and reflection of the rest of the shot.</td>', 'The bottom 1/3 of the photograph is so out of focus it is distracting to me. Subract that and I love the textures, tones, and reflection of the rest of the shot.', '2006-03-31 07:24:45.000000', NULL, 1),
(2275907, 311528, 53571, '<td valign="top">This could be a wonderful photograph with different lighting or perhaps a different moment with the "drip".</td>', 'This could be a wonderful photograph with different lighting or perhaps a different moment with the "drip".', '2006-03-31 07:25:23.000000', NULL, 1),
(2275908, 310961, 53571, '<td valign="top">Very interesting shot. Well done.</td>', 'Very interesting shot. Well done.', '2006-03-31 07:25:34.000000', NULL, 1),
(2275909, 312251, 53571, '<td valign="top">This shot is very gray for my tastes. The boarders are distracting. A different time of day/better light might yield better results.</td>', 'This shot is very gray for my tastes. The boarders are distracting. A different time of day/better light might yield better results.', '2006-03-31 07:26:12.000000', NULL, 1),
(2275910, 311387, 53571, '<td valign="top">As sunset shots go, this is slightly above average. It doesnt quite take my breath away but it is nice. It might be a 1/2 stop underexposed.</td>', 'As sunset shots go, this is slightly above average. It doesnt quite take my breath away but it is nice. It might be a 1/2 stop underexposed.', '2006-03-31 07:26:51.000000', NULL, 1),
(2275913, 312126, 53571, '<td valign="top">This is a wonderful moment. Nice job.</td>', 'This is a wonderful moment. Nice job.', '2006-03-31 07:27:20.000000', NULL, 1),
(2275914, 310087, 53571, '<td valign="top">I''m not a fan of the title but the image is a keeper. A very nice moment here.</td>', 'I''m not a fan of the title but the image is a keeper. A very nice moment here.', '2006-03-31 07:27:40.000000', NULL, 1),
(2275915, 310101, 39993, '<td valign="top">Oil painting and the cattails are glowing.</td>', 'Oil painting and the cattails are glowing.', '2006-03-31 07:27:53.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2275916, 311401, 53571, '<td valign="top">This is a great shot. I love the photo. Let me say however, it feels a little too dark to be "atmospheric". The shot also feels a little grey. Might be a 1/2 stop under exposed. Nice job overall.</td>', 'This is a great shot. I love the photo. Let me say however, it feels a little too dark to be "atmospheric". The shot also feels a little grey. Might be a 1/2 stop under exposed. Nice job overall.', '2006-03-31 07:28:32.000000', NULL, 1),
(2275917, 310656, 53571, '<td valign="top">The bubbles are great. The shot however feels slightly out of focus.</td>', 'The bubbles are great. The shot however feels slightly out of focus.', '2006-03-31 07:28:51.000000', NULL, 1),
(2275918, 310485, 53571, '<td valign="top">Showers are tough. If I had a suggestion with this shot I would speed up your shutter speed to capture the drops in mid-flight rather then the blurring you have here.</td>', 'Showers are tough. If I had a suggestion with this shot I would speed up your shutter speed to capture the drops in mid-flight rather then the blurring you have here.', '2006-03-31 07:30:11.000000', NULL, 1),
(2275919, 312207, 53571, '<td valign="top">Nice location. The shot feels rather gray and underexposed.</td>', 'Nice location. The shot feels rather gray and underexposed.', '2006-03-31 07:30:39.000000', NULL, 1),
(2275920, 310602, 53571, '<td valign="top">This is a nice shot. I really appricate it. Nice job.</td>', 'This is a nice shot. I really appricate it. Nice job.', '2006-03-31 07:30:56.000000', NULL, 1),
(2275921, 311591, 53571, '<td valign="top">Interesting perspective and lighting situation.</td>', 'Interesting perspective and lighting situation.', '2006-03-31 07:31:18.000000', NULL, 1),
(2275922, 312052, 32885, '<td valign="top">Nice car, it is a shame that it overpowers the water in this photo. It also looks a bit squashed in the frame.</td>', 'Nice car, it is a shame that it overpowers the water in this photo. It also looks a bit squashed in the frame.', '2006-03-31 07:31:41.000000', NULL, 1),
(2275924, 312007, 53571, '<td valign="top">In my opinion, this shot needs be cropped tighter to be interesting. I know its slightly interesting that "crew" appears on the concrete above the rowers but I  care about the people, not the landscape in this case.</td>', 'In my opinion, this shot needs be cropped tighter to be interesting. I know its slightly interesting that "crew" appears on the concrete above the rowers but I  care about the people, not the landscape in this case.', '2006-03-31 07:32:23.000000', NULL, 1),
(2275925, 311534, 39993, '<td valign="top">The heat ripples in the air are so visible <br/>one can almost feel the heat.</td>', 'The heat ripples in the air are so visible one can almost feel the heat.', '2006-03-31 07:32:40.000000', NULL, 1),
(2275926, 312116, 53571, '<td valign="top">To me this shot fails because there is absolutely no point of reference. The viewer can''t get their bearing in the shot. Having something in focus is important most of the time and I don''t see that here.</td>', 'To me this shot fails because there is absolutely no point of reference. The viewer can''t get their bearing in the shot. Having something in focus is important most of the time and I don''t see that here.', '2006-03-31 07:33:27.000000', NULL, 1),
