(2275928, 311494, 32885, '<td valign="top">Very pretty.</td>', 'Very pretty.', '2006-03-31 07:34:18.000000', NULL, 1),
(2275930, 311832, 53571, '<td valign="top">This is gorgeous. Might be a ribbon. I would love to see this shot with very calm water but I understand that you may be shooting with ice here. Wonderful location and shot.</td>', 'This is gorgeous. Might be a ribbon. I would love to see this shot with very calm water but I understand that you may be shooting with ice here. Wonderful location and shot.', '2006-03-31 07:34:50.000000', NULL, 1),
(2275931, 311821, 32885, '<td valign="top">Very nice. I like the colour.</td>', 'Very nice. I like the colour.', '2006-03-31 07:35:47.000000', NULL, 1),
(2275933, 312247, 32885, '<td valign="top">The reflections in this photo are breathtaking.</td>', 'The reflections in this photo are breathtaking.', '2006-03-31 07:36:53.000000', NULL, 1),
(2275934, 311778, 32885, '<td valign="top">A very good action shot IMO.</td>', 'A very good action shot IMO.', '2006-03-31 07:38:19.000000', NULL, 1),
