(2276602, 311624, 5112, '<td valign="top">Nice!  She looks like she''s having fun.</td>', 'Nice!  She looks like she''s having fun.', '2006-03-31 14:24:51.000000', NULL, 1),
(2276645, 312122, 40912, '<td valign="top">The bright spots on the water throw it off a little, and the "bump" along the bottom is a bit distracting. Otherwise, I think this is a neat photo. :) Bumping it up.</td>', 'The bright spots on the water throw it off a little, and the "bump" along the bottom is a bit distracting. Otherwise, I think this is a neat photo. :) Bumping it up.', '2006-03-31 14:47:45.000000', NULL, 1),
