(2278130, 311740, 35602, '<td valign="top">Love this photo.  Ice was pretty well done, and the water was very nice.  Need more clarity on the ice to get a really crisp edge on it.  Still, it is a favorite, and I give it an 8</td>', 'Love this photo.  Ice was pretty well done, and the water was very nice.  Need more clarity on the ice to get a really crisp edge on it.  Still, it is a favorite, and I give it an 8', '2006-04-01 09:51:14.000000', NULL, 1),
(2278167, 311874, 35602, '<td valign="top">You should have color corrected for the very yellow hue on this one.  I think the potential for a great shot is there, but the contrast on this one was a bit lacking.  Compositionally, I think you might have wanted to get closer, perhaps focusing on the section from the far left to about midway on the cliff.  Hope this helps you for future shots.</td>', 'You should have color corrected for the very yellow hue on this one.  I think the potential for a great shot is there, but the contrast on this one was a bit lacking.  Compositionally, I think you might have wanted to get closer, perhaps focusing on the section from the far left to about midway on the cliff.  Hope this helps you for future shots.', '2006-04-01 10:26:41.000000', NULL, 1),
(2278169, 312122, 35602, '<td valign="top">I KNOW this is water, but it has more of a plastic tube look.</td>', 'I KNOW this is water, but it has more of a plastic tube look.', '2006-04-01 10:27:58.000000', NULL, 1),
