(2278448, 310732, 41520, '<td valign="top">It looks cool, but the title could have been more creative.</td>', 'It looks cool, but the title could have been more creative.', '2006-04-01 13:52:17.000000', NULL, 1),
(2278450, 312207, 41520, '<td valign="top">I''m a big fan of the blurred water...maybe try a longer shutter speed next time. I think it adds more to the photograph then a fast shutter speed.</td>', 'I''m a big fan of the blurred water...maybe try a longer shutter speed next time. I think it adds more to the photograph then a fast shutter speed.', '2006-04-01 13:55:08.000000', NULL, 1),
(2278457, 311464, 41520, '<td valign="top">I would have just left the title as "When Water Crosses Fire."  The other part isn''t needed, it takes away from the photo.</td>', 'I would have just left the title as "When Water Crosses Fire."  The other part isn''t needed, it takes away from the photo.', '2006-04-01 14:00:44.000000', NULL, 1),
(2278482, 312042, 54847, '<td valign="top">´´</td>', '´´', '2006-04-01 14:19:14.000000', NULL, 1),
(2278520, 310806, 35602, '<td valign="top">Nice abstract.  Can''t wait to see how this one was done.</td>', 'Nice abstract.  Can''t wait to see how this one was done.', '2006-04-01 14:40:28.000000', NULL, 1),
(2278532, 312070, 35602, '<td valign="top">Alot of noise in this one, especially in the foreground.  Contrast needs to be more pronounced.  If you have an ability to adjust tones in your editing, you might be able to get much better contrast and less muddylooking appearance.  Compositionally you placed your subject well and the curving bank is a definite plus.</td>', 'Alot of noise in this one, especially in the foreground.  Contrast needs to be more pronounced.  If you have an ability to adjust tones in your editing, you might be able to get much better contrast and less muddylooking appearance.  Compositionally you placed your subject well and the curving bank is a definite plus.', '2006-04-01 14:44:00.000000', NULL, 1),
(2278540, 312034, 35602, '<td valign="top">This has potential to be one of those wow photos, but not as it exists currently.  A bit more dodging of the highlights and adjustment to a brighter more saturated image would have really added a lot of impact.  If you have an ability to attach a polarizer to your camera, try it and see.  If you used a polarizer, putting your stops to add more light (+) would have helped initially to get a brighter image.</td>', 'This has potential to be one of those wow photos, but not as it exists currently.  A bit more dodging of the highlights and adjustment to a brighter more saturated image would have really added a lot of impact.  If you have an ability to attach a polarizer to your camera, try it and see.  If you used a polarizer, putting your stops to add more light (+) would have helped initially to get a brighter image.', '2006-04-01 14:47:20.000000', NULL, 1),
(2278618, 311830, 55403, '<td valign="top">Beautifu!!!!</td>', 'Beautifu!!!!', '2006-04-01 16:04:31.000000', NULL, 1),
(2278623, 312100, 55403, '<td valign="top">Nice!</td>', 'Nice!', '2006-04-01 16:07:07.000000', NULL, 1),
(2278625, 310062, 24363, '<td valign="top">great picture</td>', 'great picture', '2006-04-01 16:09:46.000000', NULL, 1),
(2278626, 312249, 55403, '<td valign="top">Nice perspective!</td>', 'Nice perspective!', '2006-04-01 16:10:11.000000', NULL, 1),
(2278630, 312212, 40133, '<td valign="top">Cool idea! However, the central part of the wave is greenish, while the part on the left is deep blue, and that''s distracting. Also, the bottom looks overdone. Still good.</td>', 'Cool idea! However, the central part of the wave is greenish, while the part on the left is deep blue, and that''s distracting. Also, the bottom looks overdone. Still good.', '2006-04-01 16:14:17.000000', NULL, 1),
(2278638, 311808, 53689, '<td valign="top">this pic makes no sense to me. thats why i love it. i would give it a ten if i could vote.</td>', 'this pic makes no sense to me. thats why i love it. i would give it a ten if i could vote.', '2006-04-01 16:17:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2278648, 311247, 40133, '<td valign="top">Great shot, but IMHO the composition is too "central", I''d like the windmill more on the right. Also, I generally like saturated colors, but here the sky is too blue if compared to the water, resulting in an unnatural feeling.</td>', 'Great shot, but IMHO the composition is too "central", I''d like the windmill more on the right. Also, I generally like saturated colors, but here the sky is too blue if compared to the water, resulting in an unnatural feeling.', '2006-04-01 16:24:20.000000', NULL, 1),
(2278650, 310985, 40133, '<td valign="top">I really like the color palette. Maybe you denoised the internal part of the pipes a bit too much, but this image has a feeling.</td>', 'I really like the color palette. Maybe you denoised the internal part of the pipes a bit too much, but this image has a feeling.', '2006-04-01 16:26:32.000000', NULL, 1),
(2278651, 311771, 29168, '<td valign="top">Nice idea -- would look so much better if the web were lacking the motion blur/focus issues. Hand-held shots like this can be so frustrating -- or was it a breeze blowing the web a little? Love the colours.</td>', 'Nice idea -- would look so much better if the web were lacking the motion blur/focus issues. Hand-held shots like this can be so frustrating -- or was it a breeze blowing the web a little? Love the colours.', '2006-04-01 16:27:06.000000', NULL, 1),
(2278654, 311169, 40133, '<td valign="top">Nice burn and dodge. I would like to see less color on the clouds, though (the one just above the sun, in particular). I think it was done on purpose to emphasize the rays of light going up and right, but still it does not fit with the look of the other clouds in my opinion.</td>', 'Nice burn and dodge. I would like to see less color on the clouds, though (the one just above the sun, in particular). I think it was done on purpose to emphasize the rays of light going up and right, but still it does not fit with the look of the other clouds in my opinion.', '2006-04-01 16:32:58.000000', NULL, 1),
(2278660, 312140, 40133, '<td valign="top">Great impact!</td>', 'Great impact!', '2006-04-01 16:40:33.000000', NULL, 1),
(2278666, 312255, 3032, '<td valign="top">What a cool idea! 9</td>', 'What a cool idea! 9', '2006-04-01 16:52:21.000000', NULL, 1),
(2278668, 310423, 3032, '<td valign="top">Yeah, that''s more like it. Two years ago I said I''d only score birds like these high when they were actually doing something like catching a fish. Cool catch, for the bird and you. :)</td>', 'Yeah, that''s more like it. Two years ago I said I''d only score birds like these high when they were actually doing something like catching a fish. Cool catch, for the bird and you. :)', '2006-04-01 16:54:48.000000', NULL, 1),
(2278671, 311373, 3032, '<td valign="top">Good compo, colors work well together + good light and everything. I like it how the others are cut off, makes me concentrate on the one in front. There are two main points of interest here and for me the head of the tulip draws the most attention (probably because of the way it is lit). Nice work. 8</td>', 'Good compo, colors work well together + good light and everything. I like it how the others are cut off, makes me concentrate on the one in front. There are two main points of interest here and for me the head of the tulip draws the most attention (probably because of the way it is lit). Nice work. 8', '2006-04-01 16:58:16.000000', NULL, 1),
(2278679, 311778, 3032, '<td valign="top">Ask any Dutchman what that means and you wouldn''t call your boat that (nothing vulgar though). :)<br/>I like the expression of concentration, but the person is a bit too much in the centre. The diagonal of the paddle saves that a bit.</td>', 'Ask any Dutchman what that means and you wouldn''t call your boat that (nothing vulgar though). :)I like the expression of concentration, but the person is a bit too much in the centre. The diagonal of the paddle saves that a bit.', '2006-04-01 17:02:04.000000', NULL, 1),
(2278686, 311247, 3032, '<td valign="top">Windmills rock! :)</td>', 'Windmills rock! :)', '2006-04-01 17:06:39.000000', NULL, 1),
(2278695, 312151, 3032, '<td valign="top">Interesting composition. The eye looks like a jewel, pearly sparkle. Looks a bit too noise reduced/lack of fine detail. 7</td>', 'Interesting composition. The eye looks like a jewel, pearly sparkle. Looks a bit too noise reduced/lack of fine detail. 7', '2006-04-01 17:09:04.000000', NULL, 1),
(2278702, 312247, 36159, '<td valign="top">I''m drawn to the symetry.</td>', 'I''m drawn to the symetry.', '2006-04-01 17:11:01.000000', NULL, 1),
(2278703, 311591, 3032, '<td valign="top">Cool perspective, draws you in.</td>', 'Cool perspective, draws you in.', '2006-04-01 17:11:17.000000', NULL, 1),
(2278708, 310101, 3032, '<td valign="top">Sweet colors on those reeds in the front.</td>', 'Sweet colors on those reeds in the front.', '2006-04-01 17:12:49.000000', NULL, 1),
(2278715, 311914, 3032, '<td valign="top">Interesting photo, the lines of the walls create and odd view feeling. He''s in a formal suit, yet with a rubber ducky and without shoes on. Strange, strange, but I like it. :)<br/>When I tilt my head to the right it is even odder, makes it look like he''s standing.<br/>9</td>', 'Interesting photo, the lines of the walls create and odd view feeling. He''s in a formal suit, yet with a rubber ducky and without shoes on. Strange, strange, but I like it. :)When I tilt my head to the right it is even odder, makes it look like he''s standing.9', '2006-04-01 17:19:50.000000', NULL, 1),
